export function PdfViewer({
  title = "{{title}}",
  page = "{{page}}",
  zoom = "{{zoom}}",
  showThumbnails = {{showThumbnails}},
  accent = "{{accent}}",
}) {
  const pagePad = zoom === "150%" ? "30px 18px" : "20px 18px";
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 340, borderRadius: 10, overflow: "hidden", boxSizing: "border-box", border: "1px solid #24143018" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 12px", fontWeight: 700, color: "#FAF7F2", background: accent }}>
        <span>{title}</span>
        <span>{zoom}</span>
      </div>
      <div style={{ display: "flex", background: "#24143008" }}>
        {showThumbnails && (
          <div style={{ flex: "none", width: 40, padding: "10px 6px", display: "flex", flexDirection: "column", gap: 6 }}>
            <span style={{ display: "block", height: 24, background: "#24143022", borderRadius: 3 }} />
            <span style={{ display: "block", height: 24, background: "#24143022", borderRadius: 3 }} />
            <span style={{ display: "block", height: 24, background: "#24143022", borderRadius: 3 }} />
          </div>
        )}
        <div style={{ flex: "1 1 auto", padding: pagePad, minHeight: 90 }}>
          <span style={{ display: "block", height: 8, background: "#24143022", borderRadius: 4, marginBottom: 8 }} />
          <span style={{ display: "block", height: 8, background: "#24143022", borderRadius: 4, marginBottom: 8 }} />
          <span style={{ display: "block", height: 8, background: "#24143022", borderRadius: 4, marginBottom: 8, width: "60%" }} />
        </div>
      </div>
      <p style={{ margin: 0, padding: "8px 12px", fontSize: 12, color: "#24143099", textAlign: "center" }}>Page {page} of 8</p>
    </div>
  );
}
